#:sdk Microsoft.NET.Sdk.Web
#:property PublishAot=false

// (That second line just silences native-AOT trimming warnings that
// file-based web apps emit for reflection-based JSON — ignore it.)
//
// 33 — caching (ORIGINAL, flawed on purpose)
//
// A sales-report endpoint over an in-memory order table. The aggregation is
// "expensive" (we simulate a slow database with Thread.Sleep(800)), so:
//
//   GET /report        recomputes EVERYTHING on every single request. 800ms,
//                      every time, even when nothing changed. Watch the "ms"
//                      field in the response.
//
//   GET /report/fast   the "fix" someone shipped at 4pm on a Friday: a static
//                      Dictionary that remembers every report forever. It is
//                      fast. It is also wrong, in two separate ways.
//
// Run:   dotnet run csharp/33-caching-memory/original.cs
// Try:
//   curl "http://localhost:5033/report"                 -> ms: ~800, every time
//   curl "http://localhost:5033/report/fast"            -> ms: ~800 the first time
//   curl "http://localhost:5033/report/fast"            -> ms: ~0   after that
//
//   THE STALENESS BUG, in three commands:
//   curl -X POST "http://localhost:5033/orders?category=books&amount=999&month=2026-01"
//   curl "http://localhost:5033/report"                 -> total went up. Correct.
//   curl "http://localhost:5033/report/fast"            -> total did NOT go up.
//        The cached copy has no idea a write happened. It will keep serving
//        that stale number until the process restarts. Forever.
//
//   THE MEMORY BUG, in one command:
//   curl "http://localhost:5033/cache/stats"
//   ...then hit /report/fast?month=2026-01 ... 2026-12, plus a few typos like
//   ?month=whatever, and check /cache/stats again. Every distinct query string
//   adds an entry that is never removed. A cache with no expiry and no size
//   limit is not a cache — it is a memory leak with good manners.

using System.Diagnostics;

var app = WebApplication.CreateBuilder(args).Build();

// The "database": 2,400 orders. Pretend it is 24 million and lives on another
// machine — that is what the Thread.Sleep below is standing in for.
var categories = new[] { "books", "food", "toys", "tools" };
var orders = new List<Order>();
for (int i = 1; i <= 2400; i++)
    orders.Add(new Order(i, categories[i % 4], 5m + (i % 40), $"2026-{(i % 12) + 1:00}"));

app.MapGet("/orders/count", () => Results.Ok(new { count = orders.Count }));

// ---------------------------------------------------------------------------
// Version 1: no cache at all. Correct, and unusably slow.
// ---------------------------------------------------------------------------
app.MapGet("/report", (string? month) =>
{
    var sw = Stopwatch.StartNew();

    // FLAW #1: this runs on EVERY request. Ten users refreshing a dashboard =
    // ten identical 800ms aggregations of data that did not change between
    // them. The work is not just slow, it is *repeated* — which is the part a
    // cache can actually fix.
    Thread.Sleep(800);
    var report = BuildReport(orders, month);

    return Results.Ok(new { report, ms = sw.ElapsedMilliseconds, cached = false });
});

// ---------------------------------------------------------------------------
// Version 2: the Friday-afternoon "fix".
// ---------------------------------------------------------------------------
app.MapGet("/report/fast", (string? month) =>
{
    var sw = Stopwatch.StartNew();
    var key = month ?? "all";

    if (Cache.Entries.TryGetValue(key, out var hit))
        return Results.Ok(new { report = hit, ms = sw.ElapsedMilliseconds, cached = true });

    Thread.Sleep(800);
    var report = BuildReport(orders, month);

    // FLAW #2 (staleness): this entry is written once and never invalidated.
    // No expiry, no version, nothing watching the orders list. The moment
    // anyone POSTs an order, this cached report becomes a lie — and it is a
    // lie the server will repeat, confidently, for the rest of its life.
    //
    // FLAW #3 (unbounded growth): Cache.Entries has no size limit either. One
    // entry per distinct ?month value, including every typo and every probe
    // from a bored crawler. Nothing is ever evicted. This dictionary only
    // grows, and it grows in the same memory your app needs to serve requests.
    Cache.Entries[key] = report;

    return Results.Ok(new { report, ms = sw.ElapsedMilliseconds, cached = false });
});

app.MapPost("/orders", (string category, decimal amount, string month) =>
{
    var order = new Order(orders.Count + 1, category, amount, month);
    orders.Add(order);

    // Note what is NOT here: any attempt to tell the cache that the world
    // changed. The write side and the cache have never been introduced.
    return Results.Created($"/orders/{order.Id}", order);
});

// Proof of flaw #3: watch this number climb and never come down.
app.MapGet("/cache/stats", () => Results.Ok(new
{
    entries = Cache.Entries.Count,
    keys = Cache.Entries.Keys.ToList(),
}));

app.Run("http://localhost:5033");

Report BuildReport(List<Order> all, string? month)
{
    var scope = month ?? "all";
    var rows = month is null ? all : all.Where(o => o.Month == month).ToList();
    var byCategory = rows
        .GroupBy(o => o.Category)
        .Select(g => new CategoryTotal(g.Key, g.Sum(o => o.Amount), g.Count()))
        .OrderByDescending(c => c.Total)
        .ToList();

    return new Report(
        scope,
        rows.Count,
        rows.Sum(o => o.Amount),
        rows.Count == 0 ? 0m : Math.Round(rows.Sum(o => o.Amount) / rows.Count, 2),
        byCategory.Count == 0 ? "" : byCategory[0].Category,
        byCategory);
}

// A static dictionary that outlives every request. In a real app someone
// writes exactly this, calls it "just a small cache", and moves on.
static class Cache
{
    public static readonly Dictionary<string, Report> Entries = new();
}

record Order(int Id, string Category, decimal Amount, string Month);
record CategoryTotal(string Category, decimal Total, int Count);
record Report(string Scope, int OrderCount, decimal Total, decimal Average, string TopCategory, List<CategoryTotal> ByCategory);

# 🏋️ Practice: Caching in Memory

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. Measure before you celebrate (warm-up)

`ReportService` counts `Computations`, but nobody knows how *often* the cache actually helps. Add
`Hits`, `Misses`, and a `HitRatePercent` property, increment them in `Get`, and surface all three at
`GET /stats`. A hit rate is the only honest way to answer "is this cache earning its complexity?" —
a cache at 5% is pure overhead plus a staleness risk.
*Practices:* instrumenting a decision instead of assuming it, and the zero-traffic edge case.
**Hint:** `Interlocked.Increment(ref _hits)` for the same reason `_computations` uses it — several
requests run at once. The rate is `total == 0 ? 0 : (int)Math.Round(100.0 * Hits / total)`; guard the
divide-by-zero *before* the division, not after.
**Check offline:** add to `Tests.cs`:
```csharp
var m = new ReportService(new OrderStore(TimeSpan.Zero, Seed()), new FakeCacheStore());
m.Get(null); m.Get(null);
Check.Equal(1, m.Hits, "one hit");
Check.Equal(1, m.Misses, "one miss");
Check.Equal(50, m.HitRatePercent, "hit rate is 50%");
Check.Equal(0, new ReportService(new OrderStore(TimeSpan.Zero, Seed()), new FakeCacheStore()).HitRatePercent,
    "no traffic reports 0%, not a crash");
```
Then hammer `curl "http://localhost:5033/report"` five times and check `/stats`.

### ⭐⭐ 2. A second dimension in the key (core)

Add `?category=books` to `/report`. Pass it through `Reports.Build(orders, month, category)` (filter by
both; `null` means "all") and — the part that matters — into `KeyFor`. Then go read `KeyFor` and say
out loud what happens if you forget: *every* category would share one cached entry, and the first
caller's answer would be served to all of them.
*Practices:* the cache-key rule — **the key must contain every input that can change the answer**.
**Hint:** build the filter with `IEnumerable<Order> rows = orders;` then two conditional `Where`
calls, and `.ToList()` once at the end. For `Scope`, `category is null ? (month ?? "all") : $"{month ?? "all"}/{category}"`.
**Check offline:** add to `Tests.cs`:
```csharp
Check.Equal(44.00m, Reports.Build(sample, null, null).Total, "no filters = everything");
Check.Equal(17.00m, Reports.Build(sample, null, "books").Total, "category filter alone");
Check.Equal(10.00m, Reports.Build(sample, "2026-01", "books").Total, "both filters together");
Check.Equal(0, Reports.Build(sample, "2026-01", "toys").OrderCount, "both filters, no matching rows");
Check.Equal("all/books", Reports.Build(sample, null, "books").Scope, "the scope names the category");
Check.True(ReportService.KeyFor("2026-01", "books") != ReportService.KeyFor("2026-01", "food"),
    "categories cannot share a cache entry");
```
Then `curl "http://localhost:5033/report?category=books"` and `?category=food` — different totals, and
each is `cached:true` on its second request.

### ⭐⭐ 3. Invalidate by generation, not by hand (core)

Exercise 2 just made invalidation combinatorial: an order in `books`/`2026-01` now invalidates
`all/all`, `2026-01/all`, `all/books`, and `2026-01/books`. Miss one and it goes stale silently.
Replace `InvalidateFor` with **generational invalidation**: keep an `int _generation`, fold it into
every key, and make a write bump the counter. Every old key instantly becomes unreachable — no
`Remove` calls at all — and the orphans die at their own expiry.
*Practices:* making a whole class of bugs unrepresentable instead of remembering to avoid it.
**Hint:** `KeyFor` stops being `static` (it needs the counter): `$"report:v1:g{Generation}:{month ?? "all"}:{category ?? "all"}"`.
`InvalidateAll()` is one `Interlocked.Increment`. Update the `KeyFor` tests to call it on an instance.
**Check offline:** add to `Tests.cs`:
```csharp
var cache = new FakeCacheStore();
var svc = new ReportService(new OrderStore(TimeSpan.Zero, Seed()), cache);
Check.Equal(false, svc.Get(null, null).FromCache, "first call misses");
Check.Equal(true, svc.Get(null, null).FromCache, "second call hits");
Check.True(svc.KeyFor(null, null).Contains("g0"), "keys carry the generation");
svc.InvalidateAll();
Check.Equal(1, svc.Generation, "a write bumps the generation");
Check.True(svc.KeyFor(null, null).Contains("g1"), "...so every key changes at once");
Check.Equal(false, svc.Get(null, null).FromCache, "old entries are unreachable");
Check.Equal(0, cache.Removes, "and nothing was removed by hand");
```

### ⭐⭐ 4. Cache-aside, written once (core)

`ReportService.Get` spells out look-miss-compute-store by hand. So will the next service. Add
`T GetOrCreate<T>(string key, Func<T> factory)` to `ICacheStore` as a **default interface method** —
a method with a body, right in the interface — so `MemoryCacheStore` and `FakeCacheStore` both inherit
it and neither can spell the pattern differently. Then rewrite `Get` to use it.
*Practices:* default interface methods (C# 8), and collapsing a repeated five-step ritual into one call.
**Hint:** mark it `sealed` so implementations cannot override it — the whole point is that there is
exactly one version. Keeping `FromCache` in the result means `Get` still needs its own `TryGet` first;
that is fine, and worth noticing: `GetOrCreate` hides *whether* it was a hit, which is exactly what you
want everywhere except a demo that reports it.
**Check offline:** add to `Tests.cs`:
```csharp
ICacheStore cache = new FakeCacheStore();
Check.Equal(7, cache.GetOrCreate("k", () => 7), "GetOrCreate computes on a miss");
Check.Equal(7, cache.GetOrCreate("k", () => 999), "...and returns the stored value on a hit");
Check.Equal(1, ((FakeCacheStore)cache).Sets, "...having stored it exactly once");
```
Note the `ICacheStore cache = ...` on the first line: a default interface method is only visible
through the *interface* type, not through `FakeCacheStore`. That surprise is part of the exercise.

### ⭐⭐⭐ 5. Stop the stampede (challenge)

The comment block in `ReportService.Get` describes single-flight; build it. Add
`Task<ReportResult> GetAsync(string? month, string? category)`: check the cache, then take a **per-key**
`SemaphoreSlim` from a `ConcurrentDictionary`, check the cache *again* while holding it, and only then
compute. Make `/report` `async` and await it. Fifty simultaneous misses must produce one computation.
*Practices:* the double-checked pattern, `SemaphoreSlim` as an awaitable lock, and why the second check
is not paranoia.
**Hint:** `_gates.GetOrAdd(key, _ => new SemaphoreSlim(1, 1))` — `GetOrAdd` is atomic, so all fifty get
the same semaphore. Release in a `finally`, always. Do **not** use `lock`: you cannot `await` inside
one, and blocking a request thread for 800ms is the problem you came to solve.
**Check offline:** add to `Tests.cs` — use the *real* `MemoryCacheStore`, because `FakeCacheStore`'s
plain `Dictionary` is not thread-safe (add a `lock` to it if you want to use it here):
```csharp
using (var mem = new MemoryCache(new MemoryCacheOptions { SizeLimit = 128 }))
{
    var slow = new OrderStore(TimeSpan.FromMilliseconds(200), Seed());
    var svc = new ReportService(slow, new MemoryCacheStore(mem));

    var racers = Enumerable.Range(0, 20).Select(_ => Task.Run(() => svc.GetAsync(null, null))).ToArray();
    var results = Task.WhenAll(racers).GetAwaiter().GetResult();
    Check.Equal(1, svc.Computations, "20 simultaneous misses caused exactly ONE computation");
    Check.Equal(1, slow.Queries, "...and exactly one database query");
    Check.Equal(1, results.Count(r => !r.FromCache), "exactly one racer did the work");
    Check.True(results.All(r => r.Report.Total == 44.00m), "and everyone got the same right answer");

    Task.WhenAll(Task.Run(() => svc.GetAsync("2026-01", null)), Task.Run(() => svc.GetAsync("2026-02", null)))
        .GetAwaiter().GetResult();
    Check.Equal(3, svc.Computations, "different months are different gates, not a queue");
}
```

## Solutions

### 1. Measure before you celebrate

```csharp
// ReportService.cs
private int _hits, _misses;

public int Hits => Volatile.Read(ref _hits);
public int Misses => Volatile.Read(ref _misses);

public int HitRatePercent
{
    get
    {
        var total = Hits + Misses;
        return total == 0 ? 0 : (int)Math.Round(100.0 * Hits / total);
    }
}

public ReportResult Get(string? month)
{
    var key = KeyFor(month);
    if (_cache.TryGet<Report>(key, out var cached) && cached is not null)
    {
        Interlocked.Increment(ref _hits);
        return new ReportResult(cached, FromCache: true);
    }
    Interlocked.Increment(ref _misses);
    // ...unchanged...
}

// Program.cs
app.MapGet("/stats", (OrderStore orders, ReportService reports) => Results.Ok(new
{
    orders = orders.Count,
    databaseQueries = orders.Queries,
    reportsComputed = reports.Computations,
    hits = reports.Hits,
    misses = reports.Misses,
    hitRatePercent = reports.HitRatePercent,
}));
```

WHY: caching is a *bet*, and this is the scoreboard. A 95% hit rate says the bet paid; a 5% hit rate
says you added staleness, memory, and an invalidation bug surface for nothing, and the honest move is to
delete the cache. The counters live next to the decision they measure rather than in the endpoint —
which would only see its own requests. And `total == 0` is not a nitpick: `/stats` is the first thing
you curl on a fresh server, and a `NaN`-shaped crash there is a bad first impression.

### 2. A second dimension in the key

```csharp
// Reports.cs
public static Report Build(IReadOnlyList<Order> orders, string? month, string? category)
{
    IEnumerable<Order> rows = orders;
    if (month is not null) rows = rows.Where(o => o.Month == month);
    if (category is not null) rows = rows.Where(o => o.Category == category);
    var list = rows.ToList();                       // enumerate ONCE, at the end

    var byCategory = list
        .GroupBy(o => o.Category)
        .Select(g => new CategoryTotal(g.Key, g.Sum(o => o.Amount), g.Count()))
        .OrderByDescending(c => c.Total).ThenBy(c => c.Category)
        .ToList();

    var total = list.Sum(o => o.Amount);
    return new Report(
        Scope: category is null ? (month ?? "all") : $"{month ?? "all"}/{category}",
        OrderCount: list.Count,
        Total: total,
        Average: list.Count == 0 ? 0m : Math.Round(total / list.Count, 2),
        TopCategory: byCategory.Count == 0 ? "" : byCategory[0].Category,
        ByCategory: byCategory);
}

// ReportService.cs
public static string KeyFor(string? month, string? category)
    => $"report:v1:{month ?? "all"}:{category ?? "all"}";

public ReportResult Get(string? month, string? category)   // key now covers both
{
    var key = KeyFor(month, category);
    // ...unchanged...
}

// Program.cs
app.MapGet("/report", (string? month, string? category, ReportService reports) => { /* ...reports.Get(month, category)... */ });
```

WHY: this is the one cache rule you must never break — **the key must contain every input that can
change the answer.** Leave `category` out and `?category=books` and `?category=food` collide: whoever
asks first wins, and everyone else silently gets the wrong department's revenue. Not a crash — a
*plausible number*, which is the worst kind of wrong. A single `KeyFor` exists because this rule is
enforced by inspection, and inspecting one three-line method is possible. Note the `IEnumerable`
chaining too: composing `Where` calls builds one query that runs once at `.ToList()` rather than
materialising a list per filter (cs#04's deferred-execution lesson).

### 3. Invalidate by generation, not by hand

```csharp
// ReportService.cs
private int _generation;

public int Generation => Volatile.Read(ref _generation);

// No longer static: the key depends on the current generation.
public string KeyFor(string? month, string? category)
    => $"report:v1:g{Generation}:{month ?? "all"}:{category ?? "all"}";

/// Every cached report is now unreachable. We removed nothing — we simply
/// stopped asking for the old keys, and they die at their own expiry.
public void InvalidateAll() => Interlocked.Increment(ref _generation);

// Program.cs — the write side gets simpler, not more complicated
var order = orders.Add(dto.Category.Trim(), dto.Amount, dto.Month.Trim());
reports.InvalidateAll();
return Results.Created($"/orders/{order.Id}", order);
```

WHY: precise invalidation is correct right up until someone adds a fourth filter, at which point it is
correct *minus one key you forgot*. Generational invalidation trades precision for a guarantee: after a
write there is no reachable stale entry, by construction, however many dimensions the key grows. The
cost is that a write throws away good entries too — February was not affected by a January order, but it
is gone. That trade is usually right for a write-rarely/read-constantly dashboard and usually wrong for
a hot write path; knowing which you have is the actual skill. The orphans are also why absolute expiry
matters more here: nothing deletes them, so `SizeLimit` and the 5-minute ceiling bound the memory.

### 4. Cache-aside, written once

```csharp
// ICacheStore.cs
public interface ICacheStore
{
    bool TryGet<T>(string key, out T? value);
    void Set<T>(string key, T value);
    void Remove(string key);

    /// A DEFAULT INTERFACE METHOD (C# 8): a body, in the interface. Every
    /// implementation inherits it, and `sealed` means none of them may
    /// redefine it — there is exactly one spelling of cache-aside.
    sealed T GetOrCreate<T>(string key, Func<T> factory)
    {
        if (TryGet<T>(key, out var hit) && hit is not null) return hit;
        var made = factory();
        Set(key, made);
        return made;
    }
}

// ReportService.cs — Get keeps its own TryGet only because it reports FromCache
public ReportResult Get(string? month, string? category)
{
    var key = KeyFor(month, category);
    if (_cache.TryGet<Report>(key, out var cached) && cached is not null)
        return new ReportResult(cached, FromCache: true);

    return new ReportResult(_cache.GetOrCreate(key, () =>
    {
        var report = Reports.Build(_orders.All(), month, category);
        Interlocked.Increment(ref _computations);
        return report;
    }), FromCache: false);
}
```

WHY: default interface methods let an interface ship *derived* behaviour — things every implementation
should do identically — without an abstract base class and without copy-paste. `GetOrCreate` is derived
by definition: `TryGet` + `Set` in a fixed order, so letting a Redis store invent its own version would
only create ways to get it wrong. (The framework does exactly this, via extension methods, for
`IMemoryCache`.) The catch worth internalising is that default methods are invisible through the
concrete type — `new FakeCacheStore().GetOrCreate(...)` does not compile, `((ICacheStore)fake).GetOrCreate(...)`
does — because the method belongs to the contract, not the class. An extension method on `ICacheStore`
(cs#13) gives the same reuse with the opposite visibility rules; both are defensible.

### 5. Stop the stampede

```csharp
// ReportService.cs — add: using System.Collections.Concurrent;
private readonly ConcurrentDictionary<string, SemaphoreSlim> _gates = new();

public async Task<ReportResult> GetAsync(string? month, string? category)
{
    var key = KeyFor(month, category);

    // Fast path: a hit never touches a lock at all.
    if (_cache.TryGet<Report>(key, out var cached) && cached is not null)
        return new ReportResult(cached, FromCache: true);

    // One gate PER KEY. GetOrAdd is atomic, so every racer on this key gets
    // the same semaphore — and a racer on a different key gets a different one.
    var gate = _gates.GetOrAdd(key, _ => new SemaphoreSlim(1, 1));
    await gate.WaitAsync();
    try
    {
        // The SECOND check. While we queued, the winner may have finished and
        // filled the cache; without this, everyone who waited would compute
        // anyway and the lock would have bought nothing but a delay.
        if (_cache.TryGet<Report>(key, out var late) && late is not null)
            return new ReportResult(late, FromCache: true);

        var report = Reports.Build(_orders.All(), month, category);
        Interlocked.Increment(ref _computations);
        _cache.Set(key, report);
        return new ReportResult(report, FromCache: false);
    }
    finally
    {
        gate.Release();   // in a finally: an exception must not wedge the key forever
    }
}

// Program.cs
app.MapGet("/report", async (string? month, string? category, ReportService reports) =>
{
    var sw = System.Diagnostics.Stopwatch.StartNew();
    var result = await reports.GetAsync(month, category);
    return Results.Ok(new { report = result.Report, cached = result.FromCache, ms = sw.ElapsedMilliseconds });
});
```

WHY: this is **double-checked locking**, and both checks earn their place. The first keeps the common
case — a hit — completely lock-free, so the semaphore is only involved in the rare moment after an
expiry. The second is what actually kills the stampede: nineteen requests wait, then nineteen find the
answer already there. Delete it and you get "the stampede, but politely queued", which is *slower* than
no lock at all.

`SemaphoreSlim` rather than `lock` because you cannot `await` inside a `lock`, and a blocked request
thread is a thread Kestrel cannot use for anybody else. Per-key rather than global because a global lock
makes a January miss stall February for 800ms — a burst converted into a traffic jam. And the `finally`
is not decoration: an exception thrown while holding the gate leaves that key permanently unservable,
the kind of outage that shows up the day the database is already having a bad time.

One honest loose end: `_gates` grows one entry per distinct key and never removes them. For a bounded
key space that is fine; for user ids or search terms you would evict gates too — at which point you are
writing a cache to protect your cache, and it is time to reach for a library.

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// The test double. It is a real, working cache — just a dictionary — with two
// extra powers that make cache behaviour *observable* instead of inferred:
//
//   Sets / Removes / Hits / Misses — counters, so a test can assert "the
//     second call did not recompute" directly rather than by timing it.
//     Timing-based tests are how you get a suite that fails on a slow laptop.
//
//   ExpireAll() — pretend every entry aged out. Real expiry needs a real
//     clock; a fake lets the test say "now imagine five minutes passed" and
//     finish in microseconds.
//
// It deliberately copies the real store's behaviours (a wrong-typed entry is a
// miss; Remove on a missing key is silent) — a double that drifts from the
// real thing makes tests lie (cs#21's contract-suite lesson).

public class FakeCacheStore : ICacheStore
{
    private readonly Dictionary<string, object?> _entries = new();

    public int Sets { get; private set; }
    public int Removes { get; private set; }
    public int Hits { get; private set; }
    public int Misses { get; private set; }
    public int Count => _entries.Count;
    public IReadOnlyList<string> Keys => _entries.Keys.OrderBy(k => k).ToList();

    public bool TryGet<T>(string key, out T? value)
    {
        if (_entries.TryGetValue(key, out var raw) && raw is T typed)
        {
            Hits++;
            value = typed;
            return true;
        }
        Misses++;
        value = default;
        return false;
    }

    public void Set<T>(string key, T value)
    {
        Sets++;
        _entries[key] = value;
    }

    public void Remove(string key)
    {
        Removes++;
        _entries.Remove(key);
    }

    /// Test-only: simulate "every entry hit its expiry deadline".
    public void ExpireAll() => _entries.Clear();
}

// The SEAM (cs#21's lesson again, applied to caching). Three methods is the
// entire surface our app needs from a cache:
//
//   MemoryCacheStore  — the real one, over the framework's IMemoryCache.
//   FakeCacheStore    — the test double: same contract, no framework, and it
//                       can be told to "expire everything" on demand so tests
//                       never have to sleep.
//   (a Redis store)   — doesn't exist here, but a distributed cache
//                       (StackExchange.Redis, a NuGet package) implements
//                       exactly this shape. Zero endpoint edits.
//
// Why not have ReportService depend on IMemoryCache directly? It could — but
// then every cache test would need the framework's entry-options machinery,
// and "did we cache it?" would be answered by poking at a real cache instead
// of by a fake that simply counts. Narrow interfaces make honest doubles.

public interface ICacheStore
{
    /// True when the key is present AND holds a T. Anything else is a miss.
    bool TryGet<T>(string key, out T? value);

    /// Store (or overwrite) a value under the key, with whatever expiry policy
    /// the implementation applies. Callers deliberately cannot choose it —
    /// expiry is a *deployment* decision, not a per-call one.
    void Set<T>(string key, T value);

    /// Explicit invalidation. This is the method the write side calls.
    void Remove(string key);
}

using Microsoft.Extensions.Caching.Memory;

// The real cache: a thin adapter over IMemoryCache, which ships in the
// ASP.NET Core shared framework (no NuGet needed) and is registered with
// `builder.Services.AddMemoryCache(...)`.
//
// Everything the original got wrong is a policy decision that lives HERE, in
// one class, instead of being absent everywhere:
//
//   AbsoluteExpirationRelativeToNow — a hard ceiling. However popular an entry
//     is, it dies at five minutes and gets recomputed. This is the honesty
//     valve: it bounds how stale any answer can be, even if someone forgets an
//     invalidation call.
//
//   SlidingExpiration — an idle timeout. An entry nobody has asked for in a
//     minute is evicted early, so unpopular keys (the crawler's typo'd month)
//     do not squat in memory until their absolute deadline.
//
//   Size = 1 + SizeLimit on the cache — a hard cap on how many entries can
//     exist at once. When the cache is full, IMemoryCache evicts to make room.
//     THIS is what makes it a cache rather than a leak: it is allowed to
//     forget, which the original's Dictionary never was.
//
// Absolute and sliding together read as: "at most 5 minutes old, and dropped
// after 1 minute of neglect, whichever comes first."

public class MemoryCacheStore : ICacheStore
{
    public static readonly TimeSpan DefaultAbsolute = TimeSpan.FromMinutes(5);
    public static readonly TimeSpan DefaultSliding = TimeSpan.FromMinutes(1);

    private readonly IMemoryCache _cache;
    private readonly TimeSpan _absolute;
    private readonly TimeSpan _sliding;

    public MemoryCacheStore(IMemoryCache cache)
        : this(cache, DefaultAbsolute, DefaultSliding) { }

    // Tests use this overload to make expiry observable without waiting five
    // minutes. Same trick as injecting a clock (cs#23's practice set). It is
    // `internal` on purpose: the DI container only ever sees PUBLIC
    // constructors, so this one cannot confuse it about which to call.
    internal MemoryCacheStore(IMemoryCache cache, TimeSpan absolute, TimeSpan sliding)
    {
        _cache = cache;
        _absolute = absolute;
        _sliding = sliding;
    }

    public bool TryGet<T>(string key, out T? value)
    {
        // Note the `is T typed` check: IMemoryCache stores `object`, so a key
        // collision with a different type is a MISS, not a cast crash.
        if (_cache.TryGetValue(key, out object? raw) && raw is T typed)
        {
            value = typed;
            return true;
        }
        value = default;
        return false;
    }

    public void Set<T>(string key, T value)
    {
        _cache.Set(key, value, new MemoryCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = _absolute,
            SlidingExpiration = _sliding,
            Size = 1,
        });
    }

    public void Remove(string key) => _cache.Remove(key);
}

// The "slow database". Reads pay an artificial delay so you can *feel* what a
// cache buys you; writes are instant.
//
// The delay is a constructor parameter, not a hard-coded Thread.Sleep, for one
// reason: tests pass TimeSpan.Zero. Code that hard-codes its own slowness can
// only be tested slowly, so in practice it never gets tested at all.

public class OrderStore
{
    private readonly List<Order> _orders;
    private readonly TimeSpan _queryDelay;
    private readonly object _lock = new();
    private int _queries;

    /// The app's configuration: 2,400 orders behind an 800ms "query".
    public OrderStore() : this(TimeSpan.FromMilliseconds(800), Seed()) { }

    public OrderStore(TimeSpan queryDelay, IEnumerable<Order> seed)
    {
        _queryDelay = queryDelay;
        _orders = seed.ToList();
    }

    /// How many times the expensive read actually ran. Every cache hit is a
    /// number that did NOT go up here — that is the whole business case.
    public int Queries => Volatile.Read(ref _queries);

    public IReadOnlyList<Order> All()
    {
        if (_queryDelay > TimeSpan.Zero) Thread.Sleep(_queryDelay);   // stands in for network + disk
        Interlocked.Increment(ref _queries);
        lock (_lock) return _orders.ToList();     // a copy: callers can't mutate our list (cs#09)
    }

    public Order Add(string category, decimal amount, string month)
    {
        lock (_lock)
        {
            var order = new Order(_orders.Count + 1, category, amount, month);
            _orders.Add(order);
            return order;
        }
    }

    public int Count { get { lock (_lock) return _orders.Count; } }

    private static List<Order> Seed()
    {
        var categories = new[] { "books", "food", "toys", "tools" };
        var orders = new List<Order>(2400);
        for (int i = 1; i <= 2400; i++)
            orders.Add(new Order(i, categories[i % 4], 5m + (i % 40), $"2026-{(i % 12) + 1:00}"));
        return orders;
    }
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

var builder = WebApplication.CreateBuilder(args);

// IMemoryCache ships in the ASP.NET Core shared framework — no NuGet package.
// SizeLimit is the line the original was missing most: a cache that cannot be
// full is a dictionary that cannot be emptied. With a limit set, every entry
// must declare a Size (MemoryCacheStore gives each one 1), and the framework
// evicts the least valuable entries when the cache is full.
builder.Services.AddMemoryCache(options => options.SizeLimit = 128);

builder.Services.AddSingleton<ICacheStore, MemoryCacheStore>();
builder.Services.AddSingleton(new OrderStore());        // the 800ms "database"
builder.Services.AddSingleton<ReportService>();

var app = builder.Build();

// One report endpoint, not two. Caching is not a feature with its own URL —
// it is invisible from the outside, except that the answer arrives sooner.
app.MapGet("/report", (string? month, ReportService reports) =>
{
    var sw = System.Diagnostics.Stopwatch.StartNew();
    var result = reports.Get(month);
    return Results.Ok(new
    {
        report = result.Report,
        cached = result.FromCache,
        ms = sw.ElapsedMilliseconds,
    });
});

// The write side does two things, and the second one is the whole lesson.
app.MapPost("/orders", (NewOrder dto, OrderStore orders, ReportService reports) =>
{
    if (string.IsNullOrWhiteSpace(dto.Category))
        return Results.BadRequest(new { error = "category is required" });
    if (string.IsNullOrWhiteSpace(dto.Month))
        return Results.BadRequest(new { error = "month is required (e.g. 2026-01)" });
    if (dto.Amount <= 0)
        return Results.BadRequest(new { error = "amount must be positive" });

    var order = orders.Add(dto.Category.Trim(), dto.Amount, dto.Month.Trim());
    reports.InvalidateFor(order.Month);     // <- the line the original never had
    return Results.Created($"/orders/{order.Id}", order);
});

// Proof that hits are free: hammer /report and watch these two stay put.
app.MapGet("/stats", (OrderStore orders, ReportService reports) => Results.Ok(new
{
    orders = orders.Count,
    databaseQueries = orders.Queries,
    reportsComputed = reports.Computations,
}));

app.Run("http://localhost:5033");

public record NewOrder(string? Category, decimal Amount, string? Month);

// The DOMAIN, and nothing else. No cache, no clock, no HTTP, no database —
// just "given these orders, what does the report say?".
//
// This separation is the whole reason caching is testable here. A cache is an
// optimisation *wrapped around* a computation; if the computation is tangled
// up with the cache, you can never answer "is the number right?" separately
// from "was it a hit or a miss?". Keep the math pure and both questions get
// easy answers.

public record Order(int Id, string Category, decimal Amount, string Month);

public record CategoryTotal(string Category, decimal Total, int Count);

public record Report(
    string Scope,
    int OrderCount,
    decimal Total,
    decimal Average,
    string TopCategory,
    IReadOnlyList<CategoryTotal> ByCategory);

public static class Reports
{
    /// Pure: same orders in, same report out, every time. No side effects,
    /// nothing to mock, and — crucially for a cached value — SAFE TO SHARE,
    /// because a `record` of `record`s cannot be mutated by whoever holds it.
    public static Report Build(IReadOnlyList<Order> orders, string? month)
    {
        var rows = month is null
            ? orders
            : orders.Where(o => o.Month == month).ToList();

        var byCategory = rows
            .GroupBy(o => o.Category)
            .Select(g => new CategoryTotal(g.Key, g.Sum(o => o.Amount), g.Count()))
            .OrderByDescending(c => c.Total)
            .ThenBy(c => c.Category)          // ties broken by name: deterministic output
            .ToList();

        var total = rows.Sum(o => o.Amount);

        return new Report(
            Scope: month ?? "all",
            OrderCount: rows.Count,
            Total: total,
            Average: rows.Count == 0 ? 0m : Math.Round(total / rows.Count, 2),
            TopCategory: byCategory.Count == 0 ? "" : byCategory[0].Category,
            ByCategory: byCategory);
    }
}

// CACHE-ASIDE (also called lazy loading), the pattern in five lines:
//
//   1. look in the cache
//   2. hit?  return it
//   3. miss? do the expensive work
//   4. put the result in the cache
//   5. return it
//
// "Aside" because the cache sits *beside* the data source rather than in front
// of it: this class, not the cache, owns the decision to recompute. The other
// half — the half the original never wrote — is step 6: when the underlying
// data changes, someone must call Invalidate.
//
// Note who does what. Reports.Build is pure math. OrderStore is slow I/O.
// ICacheStore is memory. ReportService only *sequences* them, which is why it
// fits on one screen and is testable with a dictionary.

public record ReportResult(Report Report, bool FromCache);

public class ReportService
{
    private const string KeyPrefix = "report:";
    private const string AllScope = "all";

    private readonly OrderStore _orders;
    private readonly ICacheStore _cache;
    private int _computations;

    public ReportService(OrderStore orders, ICacheStore cache)
    {
        _orders = orders;
        _cache = cache;
    }

    /// How many times the report was actually built. Hits don't move it.
    public int Computations => Volatile.Read(ref _computations);

    /// One place that turns a query into a cache key. Scattering
    /// string-concatenated keys through endpoints is how invalidation starts
    /// missing entries: the writer spells the key slightly differently than
    /// the reader, and the stale copy lives on. The "v1" is a habit worth
    /// keeping — bump it and every old entry is ignored, which is the cheapest
    /// possible migration when the Report shape changes.
    public static string KeyFor(string? month) => $"{KeyPrefix}v1:{month ?? AllScope}";

    public ReportResult Get(string? month)
    {
        var key = KeyFor(month);

        if (_cache.TryGet<Report>(key, out var cached) && cached is not null)
            return new ReportResult(cached, FromCache: true);

        // ---------------------------------------------------------------
        // A note on CACHE STAMPEDE (also: dogpile, thundering herd).
        //
        // Suppose the entry expires at noon and fifty requests arrive at
        // 12:00:00. All fifty miss. All fifty start the 800ms computation.
        // The cache did not fail — it worked exactly as designed — and yet
        // the database just took fifty times its normal load at the worst
        // possible moment. Caches make outages *lumpier*, not smaller.
        //
        // The standard cure is SINGLE-FLIGHT: one lock PER KEY, taken around
        // the recompute, with a second cache check once you hold it —
        //
        //     var gate = _gates.GetOrAdd(key, _ => new SemaphoreSlim(1, 1));
        //     await gate.WaitAsync();
        //     try {
        //         if (_cache.TryGet<Report>(key, out var late)) return late;  // someone else did it
        //         ... compute, Set ...
        //     } finally { gate.Release(); }
        //
        // Per-key matters: one global lock would make a miss on the January
        // report block the February one for 800ms, converting a stampede into
        // a queue. PRACTICE.md exercise 5 has you build it for real.
        // ---------------------------------------------------------------

        var report = Reports.Build(_orders.All(), month);
        Interlocked.Increment(ref _computations);
        _cache.Set(key, report);
        return new ReportResult(report, FromCache: false);
    }

    /// Called by the WRITE side. A new order in 2026-03 changes exactly two
    /// reports: that month's, and the all-time one. Dropping both keys — and
    /// only those two — is "explicit invalidation": the cache is told, rather
    /// than left to notice, which is the difference between a stale answer
    /// lasting milliseconds and lasting until the next deploy.
    public void InvalidateFor(string month)
    {
        _cache.Remove(KeyFor(month));
        _cache.Remove(KeyFor(null));
    }
}

using Microsoft.Extensions.Caching.Memory;

public static class Tests
{
    public static int Run()
    {
        Console.WriteLine("Reports.Build: the math, with no cache anywhere near it");
        var sample = new List<Order>
        {
            new(1, "books", 10.00m, "2026-01"),
            new(2, "food",   5.50m, "2026-01"),
            new(3, "books",  7.00m, "2026-02"),
            new(4, "toys",  21.50m, "2026-02"),
        };

        var all = Reports.Build(sample, null);
        Check.Equal("all", all.Scope, "no month means the all-time report");
        Check.Equal(4, all.OrderCount, "counts every order");
        Check.Equal(44.00m, all.Total, "sums every amount");
        Check.Equal(11.00m, all.Average, "average is total / count");
        Check.Equal("toys", all.TopCategory, "top category is the biggest by total");
        Check.Equal(3, all.ByCategory.Count, "one row per category");
        Check.Equal(17.00m, all.ByCategory.First(c => c.Category == "books").Total, "books rows are summed together");
        Check.Equal(2, all.ByCategory.First(c => c.Category == "books").Count, "...and counted together");

        var jan = Reports.Build(sample, "2026-01");
        Check.Equal("2026-01", jan.Scope, "the month is echoed back as the scope");
        Check.Equal(2, jan.OrderCount, "a month report only counts that month");
        Check.Equal(15.50m, jan.Total, "a month report only sums that month");
        Check.Equal(7.75m, jan.Average, "a month report averages that month");
        Check.Equal("books", jan.TopCategory, "January's top category differs from all-time");

        var empty = Reports.Build(sample, "2026-03");
        Check.Equal(0, empty.OrderCount, "a month with no orders reports zero orders");
        Check.Equal(0m, empty.Total, "...zero total");
        Check.Equal(0m, empty.Average, "...and zero average, not a divide-by-zero crash");
        Check.Equal("", empty.TopCategory, "...and no top category");

        var ties = new List<Order> { new(1, "beta", 10m, "m"), new(2, "alpha", 10m, "m") };
        Check.Equal("alpha", Reports.Build(ties, null).ByCategory[0].Category,
            "equal totals are broken by name, so the output is deterministic");

        // The same cache-aside suite against BOTH implementations of the seam.
        // If the fake ever drifts from the framework's real cache, this catches
        // it — cs#21's contract-test idea, applied to caching.
        Console.WriteLine("Cache-aside suite vs FakeCacheStore (the double)");
        CacheAsideSuite(new FakeCacheStore(), "fake");

        Console.WriteLine("Cache-aside suite vs MemoryCacheStore (the real IMemoryCache)");
        using (var real = new MemoryCache(new MemoryCacheOptions { SizeLimit = 128 }))
            CacheAsideSuite(new MemoryCacheStore(real), "memory");

        Console.WriteLine("FakeCacheStore: the counters say what happened");
        {
            var cache = new FakeCacheStore();
            var service = new ReportService(new OrderStore(TimeSpan.Zero, Seed()), cache);

            service.Get(null);
            Check.Equal(1, cache.Misses, "the first read missed");
            Check.Equal(1, cache.Sets, "...so the result was stored");
            service.Get(null);
            Check.Equal(1, cache.Hits, "the second read hit");
            Check.Equal(1, cache.Sets, "...and stored nothing new");
            Check.Equal(1, cache.Count, "one key in the cache");
            Check.Equal(ReportService.KeyFor(null), cache.Keys[0], "and it is the key the service computed");

            // "Now imagine five minutes passed." No Thread.Sleep in sight.
            cache.ExpireAll();
            var afterExpiry = service.Get(null);
            Check.Equal(false, afterExpiry.FromCache, "an expired entry is a miss");
            Check.Equal(2, service.Computations, "...and the work is done again");
            Check.Equal(44.00m, afterExpiry.Report.Total, "the recomputed number is still correct");
        }

        Console.WriteLine("MemoryCacheStore: the framework's own behaviour");
        using (var real = new MemoryCache(new MemoryCacheOptions { SizeLimit = 128 }))
        {
            var store = new MemoryCacheStore(real);
            store.Set("k", new Order(1, "books", 3m, "2026-01"));

            Check.True(store.TryGet<Order>("k", out var got), "a stored value comes back");
            Check.Equal(3m, got!.Amount, "...unchanged");
            Check.Equal(false, store.TryGet<Order>("nope", out _), "an unknown key is a miss");
            Check.Equal(false, store.TryGet<Report>("k", out _), "a key holding the WRONG type is a miss, not a crash");

            store.Remove("k");
            Check.Equal(false, store.TryGet<Order>("k", out _), "Remove really removes");
            store.Remove("k");   // must not throw
            Check.Equal(false, store.TryGet<Order>("k", out _), "removing twice is silent");
        }

        Console.WriteLine("MemoryCacheStore: entries really do expire (the one test that waits)");
        using (var real = new MemoryCache(new MemoryCacheOptions { SizeLimit = 128 }))
        {
            // 20ms instead of 5 minutes — the policy is a constructor argument
            // precisely so this test can exist at all.
            var quick = new MemoryCacheStore(real, TimeSpan.FromMilliseconds(20), TimeSpan.FromMilliseconds(20));
            quick.Set("k", new Order(1, "books", 3m, "2026-01"));
            Check.True(quick.TryGet<Order>("k", out _), "present immediately after Set");

            Thread.Sleep(120);
            Check.Equal(false, quick.TryGet<Order>("k", out _),
                "gone after its absolute deadline — the cache is ALLOWED to forget");
        }

        Console.WriteLine("Cache keys");
        Check.Equal("report:v1:all", ReportService.KeyFor(null), "no month keys the all-time report");
        Check.Equal("report:v1:2026-01", ReportService.KeyFor("2026-01"), "a month keys its own report");
        Check.True(ReportService.KeyFor("2026-01") != ReportService.KeyFor("2026-02"),
            "different months cannot collide");

        return Check.Summary();
    }

    private static Order[] Seed() =>
    [
        new Order(1, "books", 10.00m, "2026-01"),
        new Order(2, "food",   5.50m, "2026-01"),
        new Order(3, "books",  7.00m, "2026-02"),
        new Order(4, "toys",  21.50m, "2026-02"),
    ];

    // One suite, any ICacheStore. It pins the three behaviours that separate a
    // cache from a memory leak: hits skip the work, writes are noticed, and
    // different keys are different answers.
    private static void CacheAsideSuite(ICacheStore cache, string label)
    {
        var orders = new OrderStore(TimeSpan.Zero, new[]
        {
            new Order(1, "books", 10m, "2026-01"),
            new Order(2, "food",   5m, "2026-01"),
            new Order(3, "books",  7m, "2026-02"),
        });
        var reports = new ReportService(orders, cache);

        var first = reports.Get(null);
        Check.Equal(false, first.FromCache, $"[{label}] the first call is a MISS");
        Check.Equal(1, reports.Computations, $"[{label}] a miss builds the report");
        Check.Equal(1, orders.Queries, $"[{label}] a miss hits the database");
        Check.Equal(22m, first.Report.Total, $"[{label}] and the number is right");

        var second = reports.Get(null);
        Check.Equal(true, second.FromCache, $"[{label}] the second call is a HIT");
        Check.Equal(1, reports.Computations, $"[{label}] a hit builds nothing");
        Check.Equal(1, orders.Queries, $"[{label}] a hit never touches the database");
        Check.Equal(22m, second.Report.Total, $"[{label}] and returns the same number");
        Check.True(ReferenceEquals(first.Report, second.Report),
            $"[{label}] the SAME object is handed out — safe only because Report is immutable");

        var janMiss = reports.Get("2026-01");
        Check.Equal(false, janMiss.FromCache, $"[{label}] a different month is a different key");
        Check.Equal(15m, janMiss.Report.Total, $"[{label}] and gets its own answer");
        Check.Equal(true, reports.Get("2026-01").FromCache, $"[{label}] which then caches too");

        // The original's bug, reproduced deliberately: a write with no
        // invalidation leaves a confident, wrong answer in place.
        orders.Add("toys", 100m, "2026-01");
        Check.Equal(true, reports.Get(null).FromCache, $"[{label}] a write alone does not refresh anything");
        Check.Equal(22m, reports.Get(null).Report.Total,
            $"[{label}] so the STALE total is still served (this is the original's bug)");

        // ...and the fix.
        reports.InvalidateFor("2026-01");
        var afterInvalidate = reports.Get(null);
        Check.Equal(false, afterInvalidate.FromCache, $"[{label}] invalidation forces a recompute");
        Check.Equal(122m, afterInvalidate.Report.Total, $"[{label}] which sees the new order");
        Check.Equal(true, reports.Get(null).FromCache, $"[{label}] and the fresh answer is cached again");

        var janAfter = reports.Get("2026-01");
        Check.Equal(false, janAfter.FromCache, $"[{label}] the month key was invalidated too");
        Check.Equal(115m, janAfter.Report.Total, $"[{label}] and it also sees the new order");

        // February was untouched by a January write, so it must still be cached.
        var feb = reports.Get("2026-02");
        Check.Equal(false, feb.FromCache, $"[{label}] February was never cached before");
        Check.Equal(7m, feb.Report.Total, $"[{label}] February total is unaffected by January");
        Check.Equal(true, reports.Get("2026-02").FromCache, $"[{label}] February caches like everything else");
    }
}
